def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    cs=comps(g); bg=max(cs,key=lambda x:len(x[1]))[0]
    comp_id={}
    for k,(col,cells) in enumerate(cs):
        for i,j in cells: comp_id[(i,j)]=k
    todo=[(r,c) for r in range(H) for c in range(W)
          if g[r][c] not in [g[r+dr][c+dc] for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<H and 0<=c+dc<W]]
    for r,c in todo:
        nb=[g[r+dr][c+dc] for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<H and 0<=c+dc<W]
        cnt=Counter(nb); m=max(cnt.values()); cands=[k for k,x in cnt.items() if x==m]
        if len(cands)==1: g[r][c]=cands[0]; continue
        def rect_score(col):
            best=0
            for top in range(max(0,r-6),min(H,r+7)):
                for bot in range(max(r-6,top+1),min(H,r+7)):
