                            cells=[(i,j) for i in range(top,bot+1) for j in range(left,right+1) if (i,j)!=(r,c)]
                            if all(g[i][j]==col for i,j in cells):
                                best=max(best,len(cells)/((bot-top+1)*(right-left+1)))
            return best
        objs=[]
        for col in cands:
