            ids={comp_id[(r+dr,c+dc)] for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<H and 0<=c+dc<W and g[r+dr][c+dc]==col}
            if len(ids)==1 and rect_score(col)>0: objs.append((rect_score(col),col))
        if objs: g[r][c]=max(objs)[1]
