lib='''"""Reusable ARC helpers."""
from collections import Counter

def components(g):
    """Return list of (color, cells) 4-connected components."""
    H, W = len(g), len(g[0]); seen = [[False]*W for _ in range(H)]; out = []
    for r in range(H):
        for c in range(W):
            if not seen[r][c]:
                col = g[r][c]; st = [(r, c)]; seen[r][c] = True; cells = []
                while st:
                    i, j = st.pop(); cells.append((i, j))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        a, b = i+dr, j+dc
                        if 0 <= a < H and 0 <= b < W and not seen[a][b] and g[a][b] == col:
                            seen[a][b] = True; st.append((a, b))
                out.append((col, cells))
    return out

def fill_noise_cells(g):
    """Replace isolated cells (no same-color 4-neighbor) with neighbor majority; ties resolved by object-rectangle completion, else background."""
    g = [row[:] for row in g]; H, W = len(g), len(g[0])
    cs = components(g); bg = max(cs, key=lambda x: len(x[1]))[0]
    comp_id = {}
    for k, (col, cells) in enumerate(cs):
        for i, j in cells: comp_id[(i, j)] = k
    def rect_score(r, c, col):
        best = 0
        for top in range(max(0, r-6), min(H, r+7)):
            for bot in range(max(r-6, top+1), min(H, r+7)):
                for left in range(max(0, c-6), min(W, c+7)):
                    for right in range(max(c-6, left+1), min(W, c+7)):
                        if bot-top+1 < 2 or right-left+1 < 2: continue
                        cells = [(i, j) for i in range(top, bot+1) for j in range(left, right+1) if (i, j) != (r, c)]
                        if all(g[i][j] == col for i, j in cells):
                            best = max(best, len(cells)/((bot-top+1)*(right-left+1)))
        return best
    for r in range(H):
        for c in range(W):
            if g[r][c] in [g[r+dr][c+dc] for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0 <= r+dr < H and 0 <= c+dc < W]:
                continue
            nb = [g[r+dr][c+dc] for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0 <= r+dr < H and 0 <= c+dc < W]
            cnt = Counter(nb); m = max(cnt.values()); cands = [k for k, x in cnt.items() if x == m]
            if len(cands) == 1:
                g[r][c] = cands[0]; continue
            objs = []
            for col in cands:
                if col == bg: continue
                ids = {comp_id[(r+dr, c+dc)] for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0 <= r+dr < H and 0 <= c+dc < W and g[r+dr][c+dc] == col}
                s = rect_score(r, c, col)
                if len(ids) == 1 and s > 0: objs.append((s, col))
            if objs: g[r][c] = max(objs)[1]
            elif bg in cands: g[r][c] = bg
            else: g[r][c] = cands[0]
    return g
